export const spotlightId = (number: StoryLessonNumber) => `conversational-skills-L7-C1-${number}-${spotlightEpisodes[number].skill}-en-v1`;

export function buildSpotlightLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, spotlightEpisodes[number], previous, reference, {
    id: spotlightId(number), chapterName: 'Before the Spotlight', pronunciation: spotlightPronunciation[number],
    setting: 'Spotlight Works, a fictional independent entertainment agency in Shibuya, Tokyo, with a recording studio, rented filming space and small live music venue. The series follows a separate five-person music-launch team.',
    previousSummary: index === 0 ? 'Maya Kurose has produced advertising campaigns. She is joining Spotlight Works for her first music-industry role.' : spotlightEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(7)}\nReference: Beyond the Spotlight, Chapter 1: Before the Spotlight. Owner explicitly sets Level 7 to TOEIC 550-780. Eight episodes map to slots 1-4 and 6-9; 5/10 remain dynamic checkpoints. English only, four Step A expressions, only Step B pronunciation with bold stress, no Part III or extra pronunciation commentary. Natural tutor-first dialogue, private listening, fresh reading notes and fixed English feedback. No artwork or romance. Keep Maya, Natsumi, Jisoo, Luis and Kai separate from earlier casts. Paper Skyline is Kai’s debut single, still awaiting release through this chapter. Arrangement revision is not a released master. Campaign budget has no supplied amount or release date. Both lights fail; daylight and revised settings/shot list allow filming in three of four remaining hours. The early promotional video has thousands of views; the later live-performance clip has hundreds of thousands. Comments and singer comparisons are opinions, not sales or confirmed fame. The live audience laughs with Kai after his lyric error; he does not mock fans. Luis records the performance, but uploaders/editors and their motives remain unidentified. Two publication enquiries are not booked interviews. The omitted lyric context is confirmed in the final episode; the team plans to use the original recording, but no public correction or restored reputation is confirmed. Demands to stop venue bookings are comments, not a venue ban. The major showcase invitation is on hold until resolution, not permanently cancelled or reinstated. End unresolved; do not invent future chapters.`,
  });
  lesson.storyData.storyTitle = 'Beyond the Spotlight';
  lesson.storyData.characters = [
    { id: 'maya', name: 'Maya Kurose', role: 'main', description: 'Creative producer with advertising experience. She joins her first music-industry project and promotes Kai’s launch with careful, factual communication.' },
    { id: 'natsumi', name: 'Natsumi Ito', role: 'supporting', description: 'Experienced talent manager at Spotlight Works. She coordinates opportunities and receives the final showcase call.' },
    { id: 'jisoo', name: 'Jisoo', role: 'supporting', description: 'Digital marketing strategist. She proposes short content, follows responses and notices the differently captioned version.' },
    { id: 'luis', name: 'Luis', role: 'supporting', description: 'Videographer. He adapts the studio shoot, records the live performance and checks the context missing from the edit.' },
    { id: 'kai', name: 'Kai Nakamura', role: 'supporting', description: 'Singer-songwriter preparing Paper Skyline. He values his musical identity, recovers from a lyric mistake and faces misleading publicity.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 7, chapter: 1, lessonNumber: number,
    levelBadge: 'INTERMEDIATE', chapterLabel: 'Chapter 1: Before the Spotlight', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 550-780', authoringLanguageRevision: 'toeic-v1' };
}

export function buildSpotlightChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildSpotlightLesson(number, {}, reference));
}
